#!/usr/bin/env bash
# Build Echo.app (SwiftUI menu-bar app) without Xcode project files:
# compile the Swift sources with swiftc, assemble an .app bundle, ad-hoc sign it.
set -euo pipefail

APP_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$APP_DIR/.." && pwd)"
SRC="$APP_DIR/Echo/Sources"
BUILD="$APP_DIR/build"
APP="$BUILD/Echo.app"

rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"

# Bake the repo path so the app can find the pipeline no matter where it's launched.
cat > "$SRC/Generated.swift" <<SWIFT
// AUTO-GENERATED by build.sh — do not edit.
enum BuildConfig {
    static let repoRoot = "$REPO_ROOT"
}
SWIFT

echo "Compiling Swift sources…"
swiftc \
  -O \
  -swift-version 5 \
  -target arm64-apple-macos14.0 \
  -parse-as-library \
  -framework SwiftUI -framework AppKit -framework AVFoundation \
  -framework ScreenCaptureKit -framework CoreMedia -framework UserNotifications \
  -o "$APP/Contents/MacOS/Echo" \
  "$SRC"/*.swift

cp "$APP_DIR/Echo/Info.plist" "$APP/Contents/Info.plist"
cp "$APP_DIR/Echo/AppIcon.icns" "$APP/Contents/Resources/AppIcon.icns"

# Prefer a stable self-signed identity so the cdhash-independent designated
# requirement stays constant across rebuilds → macOS Screen-Recording / Mic TCC
# grants survive rebuilds. Falls back to ad-hoc (re-grant needed each rebuild).
# Create the identity once via Keychain Access (Certificate Assistant → Code
# Signing) or the openssl+security recipe; name it "Echo Self-Signed".
IDENTITY="Echo Self-Signed"
if security find-identity -p codesigning 2>/dev/null | grep -q "$IDENTITY"; then
  echo "Signing with stable identity: $IDENTITY (TCC grants survive rebuilds)…"
  codesign --force --sign "$IDENTITY" "$APP"
else
  echo "Ad-hoc signing — '$IDENTITY' not found, TCC will re-prompt after each rebuild…"
  codesign --force --sign - "$APP"
fi

echo "Built: $APP"
echo "Run with: open \"$APP\"   (first launch will prompt for Microphone + Screen Recording)"

# Install into /Applications, because ~/Sites is excluded from Spotlight: a
# bundle that lives only in app/build/ cannot be launched from the launcher at
# all, and a copy left in /Applications silently shadows every later rebuild —
# you fix something, relaunch from Spotlight, and run week-old code.
#
# Only the primary checkout installs. A linked worktree bakes ITS OWN path into
# BuildConfig.repoRoot above, so installing a worktree build would leave
# /Applications pointing at a directory that `git worktree remove` deletes.
# Set SKIP_INSTALL=1 to build without touching /Applications.
INSTALLED="/Applications/Echo.app"
if [ -n "${SKIP_INSTALL:-}" ]; then
  echo "Skipped install (SKIP_INSTALL set)."
elif [ "$(git -C "$REPO_ROOT" rev-parse --git-dir 2>/dev/null)" \
    != "$(git -C "$REPO_ROOT" rev-parse --git-common-dir 2>/dev/null)" ]; then
  echo "Worktree build — not installing (it would bake $REPO_ROOT into /Applications)."
elif rm -rf "$INSTALLED" && ditto "$APP" "$INSTALLED"; then
  echo "Installed: $INSTALLED"
  pgrep -qf "$INSTALLED/Contents/MacOS/Echo" && echo "  (still running the old build — quit it from the menu bar and reopen)" || true
else
  echo "⚠️  Could not install to $INSTALLED — the build above is still fine."
fi
